//! Zig declarations for the Wayland/EGL/xkbcommon C APIs.
//!
//! Zig 0.17 no longer provides `@cImport`, so `protocols/bindings.zig` is
//! generated by `zig translate-c` during the build (see `build.zig`) from the
//! handwritten `bindings.h` next to this file. This module is the single
//! import point used by the Wayland backend.
pub const c = @import("protocols/bindings.zig");
